css:
.sb-world { position: absolute; inset: 0; overflow: hidden; background: var(--ground); }
/* imagery: full bleed, graded grey; .color = the one beat that keeps its real colour */
.sb-img { position: absolute; inset: 0; overflow: hidden; transform-origin: 50% 50%; }
.sb-img > img, .sb-img > video { display: block; width: 100%; height: 100%; object-fit: cover; filter: grayscale(1) contrast(1.18) brightness(.92); }
.sb-img.color > img, .sb-img.color > video { filter: saturate(.9) contrast(1.08) brightness(.95); }
.sb-vig { position: absolute; inset: 0; pointer-events: none; background: radial-gradient(ellipse 80% 70% at 50% 45%, transparent 55%, color-mix(in srgb, var(--ground) 70%, transparent) 100%), linear-gradient(transparent 62%, color-mix(in srgb, var(--ground) 60%, transparent) 100%); }
/* graticule for map-only beats: faint lat/long lines */
.sb-grat { position: absolute; inset: -10%; pointer-events: none; background-image: linear-gradient(color-mix(in srgb, var(--ink) 9%, transparent) 1.5px, transparent 1.5px), linear-gradient(90deg, color-mix(in srgb, var(--ink) 9%, transparent) 1.5px, transparent 1.5px); background-size: 180px 180px; }
/* overlay drawing: thin white lines, dashed outlines, one amber line */
.sb-svg { position: absolute; overflow: visible; pointer-events: none; }
.sb-svg .o { fill: none; stroke: var(--ink); stroke-width: 3; stroke-dasharray: 12 9; stroke-linecap: round; }
.sb-svg .l { fill: none; stroke: var(--ink); stroke-width: 2.5; stroke-linecap: round; stroke-linejoin: round; }
.sb-svg .acc { fill: none; stroke: var(--accent); stroke-width: 4; stroke-linecap: round; stroke-linejoin: round; }
.sb-svg .fill { fill: color-mix(in srgb, var(--accent) 22%, transparent); stroke: none; }
.sb-svg .dot { fill: var(--ink); }
/* reticle: ring, four ticks, centre gap (drawn by the stub) */
.sb-ret { position: absolute; width: 260px; height: 260px; margin: -130px 0 0 -130px; overflow: visible; }
.sb-ret .r { fill: none; stroke: var(--ink); stroke-width: 2.5; }
/* reading: the one number, thin and amber */
.sb-read { position: absolute; font: 200 220px/0.9 var(--font-display); letter-spacing: -.02em; color: var(--accent); white-space: nowrap; font-variant-numeric: tabular-nums; }
.sb-read small { font-size: .32em; font-weight: 300; letter-spacing: 0; margin-left: .12em; }
.sb-cap { position: absolute; font: 500 30px/1.3 var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--ink); }
.sb-cap.dim { color: var(--muted); }
/* label with a short leader dot */
.sb-tag { position: absolute; font: 600 40px/1.15 var(--font-body); color: var(--ink); white-space: nowrap; text-shadow: 0 2px 10px color-mix(in srgb, var(--ground) 80%, transparent); }
/* headline (thin, sentence case) */
.sb-title { position: absolute; left: 80px; right: 80px; font: 300 104px/1.04 var(--font-display); letter-spacing: -.02em; color: var(--ink); text-shadow: 0 2px 18px color-mix(in srgb, var(--ground) 70%, transparent); }
.sb-title .w { display: inline-block; overflow: hidden; vertical-align: top; padding: .02em .02em .04em; }
.sb-title .w > b { display: inline-block; font-weight: inherit; }
.sb-title em, .sb-title .w.k > b { font-style: normal; font-weight: 500; color: var(--accent); }
/* top meta bar: left = what we look at, right = imagery credit (always present on imagery) */
.sb-meta { position: absolute; left: 80px; right: 80px; top: 188px; display: flex; justify-content: space-between; gap: 30px; font: 500 28px/1.2 var(--font-mono); letter-spacing: .1em; text-transform: uppercase; color: color-mix(in srgb, var(--ink) 80%, transparent); text-shadow: 0 1px 6px var(--ground); }
/* phone: thin line frame around a REAL screenshot */
.sb-phone { position: absolute; padding: 12px; border-radius: 56px; border: 2.5px solid var(--ink); background: var(--ground); }
.sb-phone .screen { width: 100%; height: 100%; border-radius: 44px; overflow: hidden; background: #000; }
.sb-phone .screen > img, .sb-phone .screen > video { display: block; width: 100%; height: 100%; object-fit: cover; object-position: top; }
.sb-ring { position: absolute; border: 4px solid var(--accent); border-radius: 18px; }
.sb-svg .o, .sb-svg .l, .sb-ret .r { filter: drop-shadow(0 0 2px rgba(0,0,0,.85)) drop-shadow(0 0 6px rgba(0,0,0,.5)); }
